function testBodySearch() {
  var test = Tests.shift();
  if (test) {
    Services.prefs.setIntPref(
      "mail.matchdiacritics",
      test.matchdiacritics ?? DIACRITICS_ALWAYS
    );
    new TestSearch(
      localAccountUtils.inboxFolder,
      test.value,
      Body,
      test.op,
      test.count,
      testBodySearch
    );
  } else {
    do_test_finished();
  }
